import{_ as t,o as i,c as r,a4 as o}from"./chunks/framework.BE47AOxC.js";const m=JSON.parse('{"title":"ADR-0002 — Frontière Core / plugins","description":"Extrait de docs/adr/0002-frontiere-core-plugins.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0002 — Frontière Core / plugins","description":"Extrait de docs/adr/0002-frontiere-core-plugins.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0002-frontiere-core-plugins.md","filePath":"developpeurs/adr/0002-frontiere-core-plugins.md"}'),n={name:"developpeurs/adr/0002-frontiere-core-plugins.md"};function s(a,e,l,c,u,d){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-0002--frontière-core--plugins" tabindex="-1">ADR-0002 — Frontière Core / plugins <a class="header-anchor" href="#adr-0002--frontière-core--plugins" aria-label="Permalink to &quot;ADR-0002 — Frontière Core / plugins {#adr-0002--frontière-core--plugins}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §4.3, §17 point ouvert #2 ; plan d&#39;action agile §3.1.bis, §4</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC identifie ce point comme structurant et non tranché : <em>« Où s&#39;arrête le Core ? Les 5 blocs &quot;chiffres-clés&quot;, le bloc &quot;Découvrir&quot;, la cartographie, PayFiP sont clairement hors Core. Actualités et Agenda ? Moins évident. Sans règle écrite, le Core enflera. »</em> Le CDC propose lui-même un critère (§17 pt.2), sans le trancher formellement.</p><p>Le risque concret, déjà identifié en §4.3 du CDC : si le Page Builder (Epic E2, Sprint 3-4) commence sans cette règle actée, des blocs spécialisés au secteur public (chiffres-clés, Découvrir) risquent d&#39;être développés directement dans le Core, puis de devoir être extraits plus tard — un coût de refactorisation évitable.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p>Le Core ne contient que ce dont le Plugin SDK a besoin pour exister. Concrètement :</p><ul><li><strong>Dans le Core :</strong> <code>Container</code>, <code>Text</code>, <code>Media</code>, <code>Relation-list</code>, <code>Form</code>, <code>Embed</code> + le Block SDK et le Plugin SDK eux-mêmes.</li><li><strong>Hors Core, plugins livrés par défaut mais désinstallables :</strong> les 5 variantes de blocs « chiffres-clés », le bloc « Découvrir », la cartographie (Localiser/Situer), PayFiP, la SVE (cas de test de référence du Plugin SDK, cf. Epic E7 / jalon M7).</li><li>Cette règle s&#39;applique à <strong>tout nouveau bloc ou module</strong> proposé pendant le développement, pas seulement à la liste ci-dessus : par défaut, un bloc non strictement nécessaire au Plugin SDK est un plugin.</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Core élargi verticale publique</strong></td><td>Inclure nativement les blocs orientés collectivités (chiffres-clés, Découvrir) pour un time-to-value plus rapide sur ce marché. Écartée car elle contredit le positionnement « généraliste + verticale publique » (ADR-0005) : un Core alourdi par une seule verticale devient, de fait, un produit de niche malgré le discours produit.</td></tr><tr><td><strong>Reporter la décision à la fin de E1/E2</strong></td><td>Écartée explicitement : le risque direct est de développer des blocs dans le Core (Sprint 3-4) qu&#39;il faudra ensuite extraire — coût de refactorisation supérieur au coût de la décision anticipée.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Le Core reste petit et généraliste, ce qui sert le positionnement produit retenu (ADR-0005).</li><li>Le Plugin SDK est validé tôt (dès que des blocs &quot;hors Core&quot; doivent être développés comme plugins), au lieu d&#39;être une promesse non testée jusqu&#39;au jalon M7.</li><li>Règle applicable immédiatement dans le Sprint 3-4 (Epic E2, Page Builder) : tout bloc dont le manifeste n&#39;est pas strictement nécessaire au SDK est développé comme plugin dès le départ, pas migré après coup.</li></ul><p><strong>Négatives</strong></p><ul><li>Nécessite que le Plugin SDK (Epic E7, jalon M7) soit fonctionnel plus tôt dans les faits que sa position officielle dans la roadmap — un plugin minimal doit pouvoir tourner dès le Sprint 3-4 pour valider chaque bloc &quot;hors Core&quot;, même si le SDK complet n&#39;est formalisé qu&#39;en M7. Ce point est un risque à surveiller (voir plan d&#39;action §9).</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[ ] Vérifier au Sprint 3-4 (Epic E2) que chaque bloc développé respecte cette frontière avant merge.</li><li>[x] Anticiper un sous-ensemble minimal du Plugin SDK dès le Sprint 3-4, indépendamment du jalon M7 officiel. → <strong>Sans objet</strong> : le Plugin SDK complet (E7) est livré, cf. <a href="/teuthis-cms-distribution/developpeurs/adr/0010-etat-installation-plugins-par-tenant">ADR-0010</a>.</li></ul>',17)])])}const g=t(n,[["render",s]]);export{m as __pageData,g as default};
